const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const path = require("path");

async function main() {
  const {
    FaCloud, FaChartLine, FaIndustry, FaGlobeAmericas,
    FaUsers, FaMapMarkedAlt, FaBolt, FaExclamationTriangle
  } = require("react-icons/fa");

  function renderIconSvg(IconComponent, color, size) {
    return ReactDOMServer.renderToStaticMarkup(
      React.createElement(IconComponent, { color, size: String(size) })
    );
  }

  async function iconToBase64(IconComponent, color, size = 256) {
    const svg = renderIconSvg(IconComponent, color, size);
    const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
    return "image/png;base64," + pngBuffer.toString("base64");
  }

  // Generate all icons upfront
  const iconCloud = await iconToBase64(FaCloud, "#0D9488", 256);
  const iconChart = await iconToBase64(FaChartLine, "#DC4A2D", 256);
  const iconIndustry = await iconToBase64(FaIndustry, "#F59E0B", 256);
  const iconGlobe = await iconToBase64(FaGlobeAmericas, "#3B82F6", 256);
  const iconUsers = await iconToBase64(FaUsers, "#F59E0B", 256);
  const iconMap = await iconToBase64(FaMapMarkedAlt, "#DC4A2D", 256);
  const iconBolt = await iconToBase64(FaBolt, "#F59E0B", 256);
  const iconAlert = await iconToBase64(FaExclamationTriangle, "#F59E0B", 256);

  // Color palette - deep, authoritative climate data theme
  const C = {
    darkBg:    "0F172A",
    darkBg2:   "1E293B",
    lightBg:   "F1F5F9",
    white:     "FFFFFF",
    offWhite:  "F8FAFC",
    accentWarm:"DC4A2D",
    accentCool:"0D9488",
    accentGold:"F59E0B",
    textDark:  "1E293B",
    textMuted: "64748B",
    textLight: "F8FAFC",
    cardBg:    "FFFFFF",
    border:    "E2E8F0",
    accentBlue:"3B82F6",
    slate700:  "334155",
    slate200:  "E2E8F0",
    slate400:  "94A3B8",
    barHigh:   "DC4A2D",
    barMid:    "F59E0B",
    barLow:    "0D9488",
    barNeut:   "64748B",
    franceBg:  "ECFDF5",
    germanyBg: "FEF3C7",
  };

  function mkShadow() {
    return { type: "outer", blur: 4, offset: 2, angle: 135, color: "000000", opacity: 0.08 };
  }

  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Global Carbon Budget 2025";
  pres.title = "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities";

  const SLIDE_W = 10;
  const SLIDE_H = 5.625;
  const MARGIN = 0.6;
  const CONTENT_W = SLIDE_W - MARGIN * 2;

  // =====================================================================
  // SLIDE 1: TITLE
  // =====================================================================
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Decorative circles
    s.addShape(pres.shapes.OVAL, {
      x: 5.8, y: -1.8, w: 7, h: 7,
      fill: { color: C.accentCool, transparency: 93 }
    });
    s.addShape(pres.shapes.OVAL, {
      x: -1.5, y: 3.2, w: 5, h: 5,
      fill: { color: C.accentWarm, transparency: 95 }
    });

    // Title
    s.addText("Global CO₂ Emissions", {
      x: MARGIN, y: 1.1, w: CONTENT_W, h: 1.2,
      fontSize: 44, fontFace: "Georgia", bold: true,
      color: C.textLight, align: "left", margin: 0
    });

    // Subtitle
    s.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
      x: MARGIN, y: 2.3, w: CONTENT_W, h: 0.7,
      fontSize: 22, fontFace: "Calibri",
      color: C.slate200, align: "left", margin: 0
    });

    // Accent bar + scope
    s.addShape(pres.shapes.RECTANGLE, {
      x: MARGIN, y: 3.25, w: 0.5, h: 0.06,
      fill: { color: C.accentGold }
    });
    s.addText("1750 – 2024", {
      x: MARGIN + 0.65, y: 3.05, w: 3, h: 0.5,
      fontSize: 20, fontFace: "Georgia", bold: true,
      color: C.accentGold, align: "left", margin: 0
    });

    // Source attribution
    s.addText("Data: Global Carbon Budget 2025  |  NASA", {
      x: MARGIN, y: 4.9, w: CONTENT_W, h: 0.4,
      fontSize: 11, fontFace: "Calibri",
      color: C.slate400, align: "left", margin: 0
    });
  }

  // =====================================================================
  // SLIDE 2: ATMOSPHERIC CO2 MILESTONE
  // =====================================================================
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Decorative
    s.addShape(pres.shapes.OVAL, {
      x: 7, y: -0.8, w: 4.5, h: 4.5,
      fill: { color: C.accentCool, transparency: 94 }
    });

    // Icon
    s.addImage({ data: iconCloud, x: MARGIN, y: 0.4, w: 0.4, h: 0.4 });

    // Title
    s.addText("Atmospheric CO₂ Reaches 429 ppm", {
      x: MARGIN + 0.55, y: 0.35, w: 8, h: 0.55,
      fontSize: 26, fontFace: "Georgia", bold: true,
      color: C.textLight, align: "left", margin: 0
    });

    // Subtitle
    s.addText("50% above pre-industrial levels (~280 ppm)", {
      x: MARGIN, y: 1.0, w: 8, h: 0.35,
      fontSize: 15, fontFace: "Calibri",
      color: C.accentCool, align: "left", margin: 0
    });

    // Giant stat
    s.addText("429", {
      x: MARGIN, y: 1.6, w: 4.5, h: 1.5,
      fontSize: 80, fontFace: "Georgia", bold: true,
      color: C.textLight, align: "left", margin: 0
    });
    s.addText("ppm", {
      x: 4.2, y: 2.4, w: 2, h: 0.7,
      fontSize: 34, fontFace: "Calibri",
      color: C.accentCool, align: "left", margin: 0
    });

    // Timeline line
    const tlY = 3.6;
    s.addShape(pres.shapes.LINE, {
      x: MARGIN, y: tlY, w: CONTENT_W, h: 0,
      line: { color: C.slate700, width: 2 }
    });

    // Timeline point 1: Pre-industrial
    s.addShape(pres.shapes.OVAL, {
      x: MARGIN + 0.4 - 0.07, y: tlY - 0.07, w: 0.14, h: 0.14,
      fill: { color: C.accentCool }
    });
    s.addText("~280 ppm", {
      x: MARGIN - 0.2, y: tlY + 0.2, w: 1.5, h: 0.25,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: C.accentCool, align: "center", margin: 0
    });
    s.addText("Pre-industrial", {
      x: MARGIN - 0.2, y: tlY + 0.4, w: 1.5, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: C.slate400, align: "center", margin: 0
    });

    // Timeline point 2: 1958
    s.addShape(pres.shapes.OVAL, {
      x: MARGIN + 3.6 - 0.07, y: tlY - 0.07, w: 0.14, h: 0.14,
      fill: { color: C.accentGold }
    });
    s.addText("~315 ppm", {
      x: MARGIN + 2.9, y: tlY + 0.2, w: 1.5, h: 0.25,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: C.accentGold, align: "center", margin: 0
    });
    s.addText("1958 — Keeling Curve", {
      x: MARGIN + 2.7, y: tlY + 0.4, w: 2, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: C.slate400, align: "center", margin: 0
    });

    // Timeline point 3: 2026
    s.addShape(pres.shapes.OVAL, {
      x: MARGIN + 7.6 - 0.07, y: tlY - 0.07, w: 0.14, h: 0.14,
      fill: { color: C.accentWarm }
    });
    s.addText("429 ppm", {
      x: MARGIN + 6.9, y: tlY + 0.2, w: 1.5, h: 0.25,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: C.accentWarm, align: "center", margin: 0
    });
    s.addText("Feb 2026 — Mauna Loa", {
      x: MARGIN + 6.6, y: tlY + 0.4, w: 2.2, h: 0.22,
      fontSize: 10, fontFace: "Calibri",
      color: C.slate400, align: "center", margin: 0
    });

    // Context note
    s.addText("Current CO₂ levels are at least 1.5× the natural increase at the end of the last ice age — a change that took thousands of years then, but roughly two centuries now.", {
      x: MARGIN, y: 4.5, w: CONTENT_W, h: 0.55,
      fontSize: 11, fontFace: "Calibri", italic: true,
      color: C.slate400, align: "left", margin: 0
    });

    // Source
    s.addText("Source: NOAA Mauna Loa Observatory, February 2026", {
      x: MARGIN, y: 5.15, w: CONTENT_W, h: 0.25,
      fontSize: 9, fontFace: "Calibri",
      color: C.slate700, align: "left", margin: 0
    });
  }

  // =====================================================================
  // SLIDE 3: GLOBAL EMISSIONS SIX-FOLD SINCE 1950
  // =====================================================================
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    // Top accent bar
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: SLIDE_W, h: 0.06,
      fill: { color: C.accentWarm }
    });

    // Icon + Title
    s.addImage({ data: iconChart, x: MARGIN, y: 0.3, w: 0.35, h: 0.35 });
    s.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold", {
      x: MARGIN + 0.5, y: 0.25, w: 8, h: 0.5,
      fontSize: 24, fontFace: "Georgia", bold: true,
      color: C.textDark, align: "left", margin: 0
    });

    // Line chart with source-confirmed data points
    s.addChart(pres.charts.LINE, [{
      name: "Global CO₂ (Billion Tonnes)",
      labels: ["1750", "1950", "1990", "2024"],
      values: [0, 6, 20, 35]
    }], {
      x: 0.4, y: 0.9, w: 5.8, h: 3.8,
      showTitle: false,
      lineSize: 3,
      lineSmooth: true,
      lineDataSymbol: "circle",
      lineDataSymbolSize: 8,
      chartColors: [C.accentWarm],
      catAxisLabelColor: C.textMuted,
      catAxisLabelFontSize: 10,
      valAxisLabelColor: C.textMuted,
      valAxisLabelFontSize: 10,
      valAxisTitle: "Billion Tonnes CO₂",
      valAxisTitleColor: C.textMuted,
      valAxisTitleFontSize: 10,
      valGridLine: { color: C.border, size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "t",
      dataLabelColor: C.textDark,
      dataLabelFontSize: 10,
      showLegend: false,
      chartArea: { fill: { color: C.white }, roundedCorners: true },
    });

    // Key inflection callout cards on the right
    const cardX = 6.6;
    const cardW = 3.0;

    // Card 1: 1950
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 1.0, w: cardW, h: 1.1,
      fill: { color: C.white }, shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 1.0, w: 0.06, h: 1.1,
      fill: { color: C.accentGold }
    });
    s.addText("1950", {
      x: cardX + 0.2, y: 1.05, w: 1, h: 0.3,
      fontSize: 14, fontFace: "Georgia", bold: true,
      color: C.accentGold, margin: 0
    });
    s.addText("~6 Billion Tonnes", {
      x: cardX + 0.2, y: 1.35, w: 2.5, h: 0.3,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: C.textDark, margin: 0
    });
    s.addText("Post-war industrial expansion", {
      x: cardX + 0.2, y: 1.65, w: 2.5, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: C.textMuted, margin: 0
    });

    // Card 2: 1990
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 2.3, w: cardW, h: 1.1,
      fill: { color: C.white }, shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 2.3, w: 0.06, h: 1.1,
      fill: { color: C.accentWarm }
    });
    s.addText("1990", {
      x: cardX + 0.2, y: 2.35, w: 1, h: 0.3,
      fontSize: 14, fontFace: "Georgia", bold: true,
      color: C.accentWarm, margin: 0
    });
    s.addText(">20 Billion Tonnes", {
      x: cardX + 0.2, y: 2.65, w: 2.5, h: 0.3,
      fontSize: 16, fontFace: "Calibri", bold: true,
      color: C.textDark, margin: 0
    });
    s.addText("Nearly 4× since 1950", {
      x: cardX + 0.2, y: 2.95, w: 2.5, h: 0.3,
      fontSize: 10, fontFace: "Calibri",
      color: C.textMuted, margin: 0
    });

    // Card 3: 2024
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 3.6, w: cardW, h: 1.1,
      fill: { color: C.white }, shadow: mkShadow()
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: cardX, y: 3.6, w: 0.06, h: 1.1,
      fill: { color: C.accentCool }
    });
    s.addText("2024", {
