file.content:
s.background = { color: C.lightBg };

// Top accent bar
s.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: SLIDE_W, h: 0.06,
  fill: { color: C.accentBlue }
});

// Icon + Title
s.addImage({ data: iconGlobe, x: MARGIN, y: 0.3, w: 0.35, h: 0.35 });
s.addText("Asia Now Accounts for ~50% of Global Emissions", {
  x: MARGIN + 0.5, y: 0.25, w: 8.5, h: 0.5,
  fontSize: 22, fontFace: "Georgia", bold: true,
  color: C.textDark, align: "left", margin: 0
});

// Two side-by-side comparison panels
const panelY = 1.1;
const panelH = 3.2;
const leftW = 3.8;
const rightW = 3.8;
const gapX = 1.2;
const leftX = MARGIN;
const rightX = MARGIN + leftW + gapX;

// LEFT PANEL: 1900
s.addShape(pres.shapes.RECTANGLE, {
  x: leftX, y: panelY, w: leftW, h: panelH,
  fill: { color: C.white }, shadow: mkShadow()
});
s.addText("1900", {
  x: leftX, y: panelY + 0.15, w: leftW, h: 0.4,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: C.textDark, align: "center", margin: 0
});

// 1900 stacked bar
const barY1900 = panelY + 0.75;
const barX1900 = leftX + 0.3;
const barW1900 = leftW - 0.6;
const barH1900 = 0.9;

// Europe + US: >90%
s.addShape(pres.shapes.RECTANGLE, {
  x: barX1900, y: barY1900, w: barW1900 * 0.92, h: barH1900,
  fill: { color: C.accentWarm }
});
s.addText("Europe + US  >90%", {
  x: barX1900 + 0.2, y: barY1900 + 0.2, w: barW1900 * 0.8, h: 0.5,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: C.white, align: "center", valign: "middle", margin: 0
});

// Rest of World: <10%
s.addShape(pres.shapes.RECTANGLE, {
  x: barX1900 + barW1900 * 0.92, y: barY1900, w: barW1900 * 0.08, h: barH1900,
  fill: { color: C.slate200 }
});

// Context for 1900
s.addText("Europe and the United States dominated global emissions, accounting for more than 90% of the total. By 1950, they still represented over 85%.", {
  x: leftX + 0.3, y: barY1900 + 1.2, w: leftW - 0.6, h: 0.9,
  fontSize: 11, fontFace: "Calibri",
  color: C.textMuted, align: "left", margin: 0
});

// RIGHT PANEL: 2024
s.addShape(pres.shapes.RECTANGLE, {
  x: rightX, y: panelY, w: rightW, h: panelH,
  fill: { color: C.white }, shadow: mkShadow()
});
s.addText("2024", {
  x: rightX, y: panelY + 0.15, w: rightW, h: 0.4,
  fontSize: 28, fontFace: "Georgia", bold: true,
  color: C.textDark, align: "center", margin: 0
});

// 2024 stacked bar segments
const barY2024 = panelY + 0.75;
const barX2024 = rightX + 0.3;
const barW2024 = rightW - 0.6;
const barH2024 = 0.9;

// Asia ~50%
s.addShape(pres.shapes.RECTANGLE, {
  x: barX2024, y: barY2024, w: barW2024 * 0.50, h: barH2024,
  fill: { color: C.accentCool }
});
s.addText("Asia ~50%", {
  x: barX2024 + 0.1, y: barY2024 + 0.2, w: barW2024 * 0.4, h: 0.5,
  fontSize: 13, fontFace: "Calibri", bold: true,
  color: C.white, align: "center", valign: "middle", margin: 0
});

// US ~14%
s.addShape(pres.shapes.RECTANGLE, {
  x: barX2024 + barW2024 * 0.50, y: barY2024, w: barW2024 * 0.14, h: barH2024,
  fill: { color: C.accentWarm }
});

